package redfish
import("context";"crypto/tls";"encoding/json";"fmt";"io";"net/http";"net/url";"strings";"time")
type Client struct { base *url.URL; http *http.Client; username,password string; retries int }
func New(target,user,pass string,timeout time.Duration,insecure bool,retries int)(*Client,error){ if !strings.Contains(target,"://"){target="https://"+target}; u,e:=url.Parse(target);if e!=nil{return nil,e};u.Path=""; return &Client{u,&http.Client{Timeout:timeout,Transport:&http.Transport{TLSClientConfig:&tls.Config{InsecureSkipVerify:insecure}}},user,pass,retries},nil }
func(c *Client)Get(ctx context.Context,path string)(map[string]any,error){u:=c.base.ResolveReference(&url.URL{Path:path});var last error;for i:=0;i<=c.retries;i++{req,e:=http.NewRequestWithContext(ctx,http.MethodGet,u.String(),nil);if e!=nil{return nil,e};req.Header.Set("Accept","application/json");req.SetBasicAuth(c.username,c.password);r,e:=c.http.Do(req);if e==nil{b,re:=io.ReadAll(io.LimitReader(r.Body,10<<20));r.Body.Close();if re==nil&&r.StatusCode>=200&&r.StatusCode<300{var out map[string]any;re=json.Unmarshal(b,&out);if re==nil{return out,nil};last=re}else if re!=nil{last=re}else{last=fmt.Errorf("GET %s: %s",path,r.Status)}}else{last=e};select{case<-ctx.Done():return nil,ctx.Err();case<-time.After(time.Duration(i+1)*250*time.Millisecond):}};return nil,last}
